function saboteur(p,f,t){const o=f.from||f,tx=f.x,ty=f.y-12,slot=f.slot;if(slot===0||slot===3){const n=slot===3?8:3;for(let j=0;j<n;j++){const a=j*Math.PI*2/n,x=tx+Math.cos(a)*55,y=ty+Math.sin(a)*30;if(t<.6){const pr=Math.min(1,t/.4);drawMine(p,{x:o.x+(x-o.x)*pr,y:o.y+(y-o.y)*pr,arm:1},t);}if(slot===3)sheet(p,'bomb',.5+Math.max(0,t-.85-j*.08)*.65,1,x,y,120,120);}}else if(slot===1){if(t<1.5)drawMine(p,{x:tx,y:ty,arm:t<1.2?1:0},t);sheet(p,'bomb',.5+Math.max(0,t-1.5)*.65,1,tx,ty,190,190);}else{for(let j=0;j<4;j++)sheet(p,'bomb',.5+Math.max(0,t-j*.12)*.7,1,tx+(j-1.5)*45,ty+(j%2)*20,130,130);}}
